#' Benford Analysis
#'
#' 
#' @param data .
#' @param measurement .
#' @param digits .
#' @param showPlot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$frequencies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$digitPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$test$asDF}
#'
#' \code{as.data.frame(results$test)}
#'
#' @export
pybenford <- function(
    data,
    measurement = NULL,
    digits = 2,
    showPlot = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pybenford requires jmvcore to be installed (restart may be required)")

    if ( ! missing(measurement)) measurement <- jmvcore::resolveQuo(jmvcore::enquo(measurement))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(measurement), measurement, NULL))


    options <- pybenfordOptions$new(
        measurement = measurement,
        digits = digits,
        showPlot = showPlot,
        showConsole = showConsole)

    analysis <- pybenfordClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

